	var word int32 = oil.OilWord(answer, at, 0, 0, 10, 20, 0, 900, 1701734144, 0, -1, 0)
	oil.OilWordCp(answer, at, word, 65)
	port.CellsPush(values, 8)
	port.CellsPush(values, 101)
	port.CellsPush(values, 110)
	port.CellsPush(values, 103)
	port.CellsPush(values, 95)
	port.CellsPush(values, 98)
	port.CellsPush(values, 101)
	port.CellsPush(values, 115)
	port.CellsPush(values, 116)
	oil.OilScPut(answer, at, 3, 3, 0, values, 0, 9)
	oil.OilEnd(answer, at)
	oilsrc.OxsRecord(answer, at, views, runs, run, lines, source)
